import { createFileRoute } from "@tanstack/react-router";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { trpc } from "@/utils/trpc";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
  Award,
  Download,
  Eye,
  CheckCircle,
  XCircle,
  AlertCircle,
  ShieldCheck,
} from "lucide-react";
import { z } from "zod";

export const Route = createFileRoute(
  "/(core)/dashboard/pelatihan/$enrollmentId/sertifikat",
)({
  params: z.object({
    enrollmentId: z.string(),
  }),
  component: UserCertificateComponent,
});

function UserCertificateComponent() {
  const { enrollmentId } = Route.useParams();
  const queryClient = useQueryClient();

  // Queries
  const {
    data: eligibility,
    isLoading: isLoadingEligibility,
    refetch: refetchEligibility,
  } = useQuery(
    trpc.pelatihan.certificate.checkEligibility.queryOptions({ enrollmentId }),
  );

  const { data: certificate, isLoading: isLoadingCert } = useQuery(
    trpc.pelatihan.certificate.getMyCertificate.queryOptions({ enrollmentId }),
  );

  const { data: enrollment } = useQuery(
    trpc.pelatihan.enrollment.getUserEnrollmentById.queryOptions({
      id: enrollmentId,
    }),
  );

  // Mutations
  const requestCertMutation = useMutation(
    trpc.pelatihan.certificate.requestCertificate.mutationOptions({
      onSuccess: () => {
        queryClient.invalidateQueries({
          queryKey: [["pelatihan", "certificate"]],
        });
        queryClient.invalidateQueries({
          queryKey: [["pelatihan", "enrollment"]],
        });
        refetchEligibility();
        toast.success("Selamat! Sertifikat Anda telah berhasil diterbitkan.");
      },
      onError: (err) => {
        toast.error(`Gagal menerbitkan sertifikat: ${err.message}`);
      },
    }),
  );

  const handleRequestCertificate = () => {
    const promise = requestCertMutation.mutateAsync({ enrollmentId });
    toast.promise(promise, {
      loading: "Sedang menerbitkan sertifikat resmi Anda...",
      success: "Sertifikat diterbitkan!",
      error: "Gagal memproses penerbitan sertifikat.",
    });
  };

  const isLoading = isLoadingEligibility || isLoadingCert;

  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="flex flex-col items-center gap-2 text-slate-500">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-600 border-t-transparent" />
          <p className="text-xs">Memeriksa kelayakan sertifikat...</p>
        </div>
      </div>
    );
  }

  // Already issued certificate view
  if (certificate) {
    return (
      <div className="mx-auto max-w-3xl space-y-6 font-['Poppins']">
        <div className="space-y-6 rounded-2xl border border-slate-200 bg-white p-6 text-center shadow-sm md:p-8">
          <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-emerald-50 text-emerald-600">
            <Award className="h-10 w-10" />
          </div>

          <div className="space-y-2">
            <h2 className="font-['Plus_Jakarta_Sans'] text-2xl font-extrabold text-slate-900">
              Sertifikat Anda Telah Terbit!
            </h2>
            <p className="text-xs text-slate-500">
              Selamat atas kelulusan Anda dalam program pelatihan resmi Balai
              K3.
            </p>
          </div>

          {/* Certificate display card */}
          <div className="flex flex-col items-center justify-between gap-6 rounded-2xl border border-slate-100 bg-slate-50 p-6 text-left md:flex-row">
            <div className="space-y-3">
              <div>
                <span className="text-[10px] font-bold text-slate-400 uppercase">
                  Nomor Sertifikat
                </span>
                <p className="font-mono text-sm font-bold text-slate-800">
                  {certificate.certificateNumber}
                </p>
              </div>
              <div>
                <span className="text-[10px] font-bold text-slate-400 uppercase">
                  Tanggal Kelulusan
                </span>
                <p className="text-xs font-semibold text-slate-700">
                  {new Date(certificate.completionDate).toLocaleDateString(
                    "id-ID",
                    {
                      day: "numeric",
                      month: "long",
                      year: "numeric",
                    },
                  )}
                </p>
              </div>
              <div className="flex items-center gap-1.5 text-[10px] font-bold text-emerald-600">
                <ShieldCheck className="h-4 w-4" />
                Terverifikasi secara digital
              </div>
            </div>

            <div className="flex w-full flex-col gap-2.5 md:w-auto">
              <a
                href={certificate.documentUrl}
                target="_blank"
                rel="noreferrer"
                className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-5 text-xs font-bold text-white shadow-md shadow-blue-500/10 transition hover:bg-blue-700 md:w-auto"
              >
                <Download className="h-4 w-4" /> Unduh Sertifikat (PDF)
              </a>
              <a
                href={`/verify/certificate/${certificate.verificationToken}`}
                target="_blank"
                rel="noreferrer"
                className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-5 text-xs font-bold text-slate-600 transition hover:bg-slate-50 md:w-auto"
              >
                <Eye className="h-4 w-4" /> Pratinjau Lembar Verifikasi
              </a>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const isEligible = eligibility?.eligible;

  return (
    <div className="mx-auto max-w-3xl space-y-6 font-['Poppins']">
      <div className="space-y-6 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm md:p-8">
        <div className="flex items-center gap-3 border-b pb-4">
          <Award className="h-8 w-8 text-blue-600" />
          <div>
            <h2 className="font-['Plus_Jakarta_Sans'] text-lg font-extrabold text-slate-800">
              Sertifikat Kelulusan
            </h2>
            <p className="text-xs text-slate-500">
              Selesaikan semua persyaratan berikut untuk mendapatkan sertifikat
              kelulusan digital Anda.
            </p>
          </div>
        </div>

        {/* Requirements check list */}
        <div className="space-y-4">
          <h3 className="text-xs font-bold tracking-wider text-slate-700 uppercase">
            Persyaratan Kelulusan:
          </h3>

          <div className="space-y-2.5">
            {/* 1. Materials */}
            <div className="flex items-start gap-3 rounded-xl border border-slate-100 bg-slate-50/50 p-4">
              <div className="mt-0.5">
                {enrollment && enrollment.progressPercentage === 100 ? (
                  <CheckCircle className="h-5 w-5 text-emerald-500" />
                ) : (
                  <XCircle className="h-5 w-5 text-slate-300" />
                )}
              </div>
              <div className="space-y-1">
                <p className="text-xs font-bold text-slate-800">
                  Selesaikan Semua Materi Pembelajaran
                </p>
                <p className="text-[11px] text-slate-500">
                  {enrollment
                    ? `Progress Anda: ${enrollment.progressPercentage}% selesai.`
                    : "Belum mulai."}
                </p>
              </div>
            </div>

            {/* 2. Score */}
            <div className="flex items-start gap-3 rounded-xl border border-slate-100 bg-slate-50/50 p-4">
              <div className="mt-0.5">
                {enrollment &&
                enrollment.finalScore !== null &&
                enrollment.finalScore >=
                  (enrollment.pelatihan?.minimumScore ?? 70) ? (
                  <CheckCircle className="h-5 w-5 text-emerald-500" />
                ) : (
                  <XCircle className="h-5 w-5 text-slate-300" />
                )}
              </div>
              <div className="space-y-1">
                <p className="text-xs font-bold text-slate-800">
                  Lulus Ujian (Post-Test / Quiz)
                </p>
                <p className="text-[11px] text-slate-500">
                  Batas nilai minimum kelulusan:{" "}
                  <span className="font-bold text-slate-700">
                    {enrollment?.pelatihan?.minimumScore ?? 70}
                  </span>
                  . Nilai Anda saat ini:{" "}
                  <span className="font-bold text-blue-600">
                    {enrollment?.finalScore ?? "Belum ujian"}
                  </span>
                  .
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Action Button */}
        {isEligible ? (
          <div className="space-y-4 rounded-xl border border-blue-100 bg-blue-50 p-5 text-center">
            <p className="text-xs font-bold text-blue-800">
              Selamat! Anda telah memenuhi semua kriteria kelulusan pelatihan
              ini.
            </p>
            <Button
              onClick={handleRequestCertificate}
              disabled={requestCertMutation.isPending}
              className="h-11 w-full rounded-xl bg-blue-600 px-6 text-xs font-bold text-white shadow-md shadow-blue-500/10 hover:bg-blue-700 md:w-auto"
            >
              {requestCertMutation.isPending
                ? "Sedang Menerbitkan..."
                : "Terbitkan Sertifikat Resmi"}
            </Button>
          </div>
        ) : (
          <div className="flex items-start gap-2.5 rounded-xl border border-slate-100 bg-slate-50 p-4 text-xs text-slate-500">
            <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-amber-500" />
            <div>
              <strong>Informasi:</strong> Sertifikat belum dapat diterbitkan.
              Pastikan Anda telah membaca semua materi pelajaran dan lulus ujian
              post-test dengan nilai di atas batas minimal kelulusan.
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
